import React from "react";
import { useNavigate, useParams } from "react-router-dom";
import { motion } from "framer-motion";

const Sidebar = ({ showButton = true }) => {
  const navigate = useNavigate();
  const { id } = useParams();

  const modulos = [
    "Aula 01 – Bem Vindo",
    "Aula 02 – Liderança",
    "Aula 03 – Desenvolvimento",
    "Aula 04 – Propósito",
    "Aula 05 – Estilos",
    "Aula 06 – Bônus",
  ];

  // Animação de saída (ao voltar para a Home)
  const handleVoltar = () => {
    // Usa o Framer Motion para animação antes de navegar
    const sidebar = document.querySelector(".sidebar");
    if (sidebar) {
      sidebar.animate(
        [
          { transform: "translateX(0)", opacity: 1 },
          { transform: "translateX(-100%)", opacity: 0 },
        ],
        { duration: 400, easing: "ease-in-out" }
      );
    }
    setTimeout(() => navigate("/"), 350); // Espera a animação terminar
  };

  return (
    <motion.aside
      className="sidebar w-72 bg-gradient-to-b from-[#B95758] to-[#e14d3a] text-white p-6 fixed top-0 left-0 h-full flex flex-col justify-between shadow-lg"
      initial={{ x: -100, opacity: 0 }}
      animate={{ x: 0, opacity: 1 }}
      exit={{ x: -100, opacity: 0 }}
      transition={{ duration: 0.4, ease: "easeInOut" }}
    >
      {/* Cabeçalho com seta */}
      <div className="flex items-center gap-3 mb-6">
        <button
          onClick={handleVoltar}
          aria-label="Voltar para a página inicial"
          className="p-2 rounded-full hover:bg-[#ffffff22] transition"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="w-5 h-5 text-white hover:text-yellow-300 transition"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>

        <h2 className="text-lg font-bold uppercase tracking-wide select-none">
          MÓDULOS
        </h2>
      </div>

      {/* Lista de módulos */}
      <ul className="space-y-3 text-sm">
        {modulos.map((modulo, i) => (
          <li
            key={i}
            onClick={() => navigate(`/video/${i + 1}`)}
            className="hover:text-yellow-200 cursor-pointer transition"
          >
            {modulo}
          </li>
        ))}
      </ul>

      {/* Material de Apoio */}
      {showButton && (
        <button
          onClick={() => navigate(`/materiais/${id || 1}`)}
          className="w-full bg-white text-[#B95758] font-semibold py-2 rounded-md hover:bg-gray-100 transition shadow-sm"
        >
          Material de Apoio
        </button>
      )}
    </motion.aside>
  );
};

export default Sidebar;
